sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var number = api.data.look_up_a_single_record_1.result.number.displayValue;
    var traveller = api.data.look_up_a_single_record_1.result.traveller.displayValue;
    var leaving_from = api.data.look_up_a_single_record_1.result.leaving_from.displayValue;
    var going_to = api.data.look_up_a_single_record_1.result.going_to.displayValue;
    var trip_type = api.data.look_up_a_single_record_1.result.trip_type.displayValue;
    var cabin = api.data.look_up_a_single_record_1.result.cabin.displayValue;

    //var opened = api.data.look_up_a_single_record_1.result.opened_at.displayValue;
    //var employee = api.data.look_up_a_single_record_1.result.employee.displayValue;
    //var state = api.data.look_up_a_single_record_1.result.state.displayValue;
    return [{
            "label": "Number",
            "value": {
                "type": "string",
                "value": number
            }
        },
        {
            "label": "Traveller",
            "value": {
                "type": "string",
                "value": traveller
            }
        },
        {
            "label": "Leaving from",
            "value": {
                "type": "string",
                "value": leaving_from
            }
        },
        {
            "label": "Going to",
            "value": {
                "type": "string",
                "value": going_to
            }
        },
        {
            "label": "Trip type",
            "value": {
                "type": "string",
                "value": trip_type
            }
        },
        {
            "label": "Cabin class",
            "value": {
                "type": "string",
                "value": cabin
            }
        }
    ];
}
